    hymn: {
      id: "pentecost-liturgy-your-resurrection",
      title: "Ⲧⲏⲛ Ⲁ̀ⲛⲁⲥⲧⲁⲥⲓⲛ (Your Resurrection (Feast of Resurrection))",
      versions: [
        { language: 'coptic', text: "Ⲡⲓⲗⲁⲟⲥ:\n\nⲦⲏⲛ Ⲁ̀ⲛⲁⲥⲧⲁⲥⲓⲛ ⲥⲟⲩ Ⲭ̀ⲣⲓⲥⲧⲉ Ⲥⲱⲧⲏⲣ: ⲁⲅⲅⲉⲗⲓ ⲩⲙⲛⲟⲩⲥⲓⲛ ⲉⲛ ⲟⲩⲣⲁⲛⲓⲥ: ⲕⲉ ⲏ̀ⲙⲁⲥ ⲧⲟⲩⲥ ⲉ̀ⲡⲓ ⲅⲩⲥ ⲕⲁⲧⲁⲝⲓⲱⲥⲟⲛ: ⲉⲛ ⲕⲁⲑⲁⲣⲁ ⲕⲁⲣⲇⲓⲁ ⲥⲉ ⲇⲟⲝⲁⲍⲓⲛ." },
        { language: 'englishCoptic', text: "Pilaos:\n\nTēn Anastasin sou Ekhriste Sōtēr: aggeli umnousin en ouranis: ke ēmas tous epi gus kataksiōson: en kathara kardia se doksazin." },
        { language: 'english', text: "People:\n\nO Christ our Savior, the angels in heaven praise Your resurrection.We ask You to make us worthy, we who are on earth, to forever glorify You with pure hearts." },
        { language: 'arabic', text: "الشعب:\n\nأيها المسيح مخلصنا، أن الملائكة لا يزالون في السماء يسبحون قيامتك، ولذلك نضرع إليك فأهلنا، نحن الذين على الأرض، أن نكون ممجدين إياك بقلوب نقية أبداً." },
        { language: 'englishArabic', text: "Esh-Sha'b:\n\nAyyuha el-Maseeh mukhallisuna, inna el-mala'ika la yazaloun fis-sama' yusabbihouna qiyamatak, wa li-dhalika nadra'u ilayka fa-ahhilna, nahnu elladheena 'ala el-ard, an nakoun mumaggideen iyyaka bi-qulubin naqiyya abadan." },
      ],
    },
